"use strict";
const assert=require("node:assert/strict");const fs=require("node:fs");const path=require("node:path");const test=require("node:test");const {startTemporaryProto05Server}=require("./helpers/temporary-proto05-server");
const file=path.resolve(__dirname,"..","..","data","activities.json");const source=JSON.parse(fs.readFileSync(file,"utf8"));const clone=value=>JSON.parse(JSON.stringify(value));
function payload(a){return {title:a.title,description:a.description,instruction:a.instruction,pedagogicalQuestion:a.pedagogicalQuestion,videoId:a.video.id,segments:a.segments,speakers:a.speakers,languages:a.languages,languageIntervals:a.languageIntervals,phenomena:a.phenomena,layers:a.layers,teacherAnnotations:a.teacherAnnotations,overlays:a.overlays,layerConfiguration:a.layerConfiguration}}
test("séparation, validation et duplication des overlays sur une copie temporaire",{timeout:15000},async t=>{const canonical=clone(source);const historical=canonical.activities[0];await t.test("migration sans double représentation",()=>{assert.equal(canonical.activities.length,5);assert.ok(historical.overlays.length);assert.equal(historical.teacherAnnotations.some(a=>Object.prototype.hasOwnProperty.call(a,"overlay")),false);for(const overlay of historical.overlays){const annotation=historical.teacherAnnotations.find(a=>a.id===overlay.annotationId),segment=historical.segments.find(s=>s.id===annotation.segmentId);assert.equal(overlay.startMs,segment.startMs);assert.equal(overlay.endMs,segment.endMs)}});const temporary=await startTemporaryProto05Server(canonical,"proto05-overlay-");try{const base=`${temporary.baseUrl}/api/proto05/activities/${historical.id}/authoring`;let activity=(await(await fetch(`${temporary.baseUrl}/api/proto05/activities/${historical.id}`)).json()).activity;await t.test("overlay autonome",async()=>{activity.overlays.push({id:"overlay-autonomous-test",startMs:303000,endMs:304000,title:"Autonome",text:"Texte autonome",layerIds:[]});const response=await fetch(base,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(payload(activity))});assert.equal(response.status,200);activity=(await response.json()).activity;assert.equal(activity.overlays.at(-1).annotationId,undefined)});await t.test("overlay lié",async()=>{const annotation=activity.teacherAnnotations[0];activity.overlays.push({id:"overlay-linked-test",annotationId:annotation.id,startMs:305000,endMs:306000,title:"Lié",text:"Texte lié",layerIds:[]});const response=await fetch(base,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(payload(activity))});assert.equal(response.status,200)});await t.test("temps invalides refusés sans écriture",async()=>{const invalid=clone(activity);invalid.overlays.find(o=>o.id==="overlay-linked-test").endMs=invalid.overlays.find(o=>o.id==="overlay-linked-test").startMs;const before=fs.readFileSync(temporary.dataFile,"utf8");const response=await fetch(base,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(payload(invalid))});assert.equal(response.status,400);assert.equal(fs.readFileSync(temporary.dataFile,"utf8"),before)});await t.test("duplication remappe les overlays",async()=>{const response=await fetch(`${temporary.baseUrl}/api/proto05/activities/${historical.id}/duplicate`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({title:"Copie overlay"})});assert.equal(response.status,201);const copy=(await response.json()).activity;assert.equal(copy.overlays.length,activity.overlays.length);assert.ok(copy.overlays.every(o=>o.id!==activity.overlays.find(x=>x.id===o.id)?.id));assert.ok(copy.overlays.filter(o=>o.annotationId).every(o=>copy.teacherAnnotations.some(a=>a.id===o.annotationId)))}); }finally{await temporary.cleanup()}});
